class Solution {
public:
    int countDistinctIntegers(std::vector<int>& nums) {
        std::unordered_set<int> s(nums.begin(), nums.end());
        for (int x : nums) {
            int rev = 0, temp = x;
            while (temp > 0) {
                rev = rev * 10 + (temp % 10);
                temp /= 10;
            }
            s.insert(rev);
        }
        return s.size();
    }
};

class Solution {
    public int countDistinctIntegers(int[] nums) {
        java.util.Set<Integer> s = new java.util.HashSet<>();
        for (int x : nums) {
            s.add(x);
            int rev = 0, temp = x;
            while (temp > 0) {
                rev = rev * 10 + (temp % 10);
                temp /= 10;
            }
            s.add(rev);
        }
        return s.size();
    }
}

var countDistinctIntegers = function(nums) {
    const s = new Set(nums);
    for (const x of nums) {
        let rev = 0, temp = x;
        while (temp > 0) {
            rev = rev * 10 + (temp % 10);
            temp = Math.floor(temp / 10);
        }
        s.add(rev);
    }
    return s.size;
};
